mapper.update:
UPDATE sgtransit_complaint
SET complaint_status=#{status},
    version=version+1,
    updated_at=CURRENT_TIMESTAMP
WHERE complaint_no=#{complaintNo}
  AND version=#{expectedVersion}

mapper.delete:
